package com.johnny.hotel.service.impl;
import com.johnny.hotel.dto.pricing.*;import com.johnny.hotel.entity.*;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.*;import com.johnny.hotel.pricing.*;import com.johnny.hotel.service.PricingService;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.math.*;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.*;import static com.johnny.hotel.service.support.BillingRules.*;
@Service @RequiredArgsConstructor public class PricingServiceImpl implements PricingService{
 private final RoomTypeMapper types;private final RoomRateMapper rates;private final PricingMapper pricing;private final Clock clock;
 @Override public RoomPriceQuote quoteRoomType(Long type,LocalDate start,LocalDate end){var decisions=explain(type,start,end);var nights=decisions.stream().map(d->new NightlyRate(d.getStayDate(),type,d.getFinalRate(),d.getRateSource(),d.getDynamicPolicyId(),d.getManualOverrideId())).toList();var total=money(nights.stream().map(NightlyRate::getPrice).reduce(BigDecimal.ZERO,BigDecimal::add),10);return new RoomPriceQuote(type,start,end,Math.toIntExact(ChronoUnit.DAYS.between(start,end)),nights,total);}
 @Override public List<PricingDecision> explain(Long type,LocalDate start,LocalDate end){dates(start,end);var rt=types.selectById(type);require(rt!=null&&rt.getStatus()==com.johnny.hotel.enums.RoomTypeStatus.ENABLED.getCode(),"Room type does not exist or is disabled");var calendar=rates.selectByRoomTypeIdAndDateRange(type,start,end).stream().collect(java.util.stream.Collectors.toMap(RoomRate::getRateDate,x->x));var policy=pricing.active();List<OccupancyBand> os=policy==null?List.of():pricing.occupancy(policy.getId());List<BookingWindowBand> ws=policy==null?List.of():pricing.windows(policy.getId());List<DynamicPricingCell> cs=policy==null?List.of():pricing.cells(policy.getId());var out=new ArrayList<PricingDecision>();for(LocalDate d=start;d.isBefore(end);d=d.plusDays(1)){var cal=calendar.get(d);BigDecimal base=money(cal==null?rt.getBasePrice():cal.getPrice(),10);int sell=pricing.sellable(), committed=pricing.committed(d);BigDecimal occ=sell==0?new BigDecimal("100.00"):BigDecimal.valueOf(committed).multiply(BigDecimal.valueOf(100)).divide(BigDecimal.valueOf(sell),2,RoundingMode.HALF_UP);int lead=Math.max(0,(int)ChronoUnit.DAYS.between(LocalDate.now(clock),d));OccupancyBand ob=null;BookingWindowBand wb=null;BigDecimal adj=BigDecimal.ZERO,raw=base,recommended=base;String source=cal==null?"BASE":cal.getRateSource();if(policy!=null){int pct=occ.setScale(0,RoundingMode.FLOOR).intValue();ob=os.stream().filter(x->pct>=x.getLowerInclusive()&&pct<x.getUpperExclusive()).findFirst().orElseThrow(()->new BusinessException("Active policy has no occupancy band"));wb=ws.stream().filter(x->lead>=x.getMinDays()&&(x.getMaxDays()==null||lead<=x.getMaxDays())).findFirst().orElseThrow(()->new BusinessException("Active policy has no booking window band"));var obId=ob.getId();var wbId=wb.getId();var cell=cs.stream().filter(x->x.getOccupancyBandId().equals(obId)&&x.getBookingWindowBandId().equals(wbId)).findFirst().orElseThrow(()->new BusinessException("Active pricing matrix is incomplete"));adj=cell.getAdjustmentPercent();raw=calculatedNightlyRate(base.multiply(BigDecimal.ONE.add(adj.divide(BigDecimal.valueOf(100),8,RoundingMode.HALF_UP))));recommended=clamp(raw,base.multiply(policy.getMinimumMultiplier()),base.multiply(policy.getMaximumMultiplier()));source="DYNAMIC";}var override=pricing.override(type,d);BigDecimal fin=recommended;if(override!=null){if("FIXED_RATE".equals(override.getOverrideType())){fin=money(override.getOverrideValue(),10);source="MANUAL_FIXED";}else{var adjusted=recommended.multiply(BigDecimal.ONE.add(override.getOverrideValue().divide(BigDecimal.valueOf(100),8,RoundingMode.HALF_UP)));fin=policy==null?calculatedNightlyRate(adjusted):clamp(adjusted,base.multiply(policy.getMinimumMultiplier()),base.multiply(policy.getMaximumMultiplier()));source="MANUAL_PERCENT";}}require(fin.signum()>0,"Nightly rate must be positive");out.add(PricingDecision.builder().stayDate(d).roomTypeId(type).baseRate(base).propertyOccupancy(occ).sellableRoomCount(sell).committedRoomCount(committed).leadDays(lead).dynamicPolicyId(policy==null?null:policy.getId()).dynamicPolicyVersion(policy==null?null:policy.getVersionNo()).occupancyBand(ob==null?null:ob.getLabel()).bookingWindowBand(wb==null?null:wb.getLabel()).dynamicAdjustmentPercent(adj).rawDynamicRate(raw).dynamicRecommendedRate(recommended).manualOverrideId(override==null?null:override.getId()).manualOverrideType(override==null?null:override.getOverrideType()).manualValue(override==null?null:override.getOverrideValue()).finalRate(fin).rateSource(source).build());}return out;}
 private BigDecimal calculatedNightlyRate(BigDecimal calculated){return money(calculated.setScale(2,RoundingMode.HALF_UP),10);}
 private BigDecimal clamp(BigDecimal x,BigDecimal min,BigDecimal max){return calculatedNightlyRate(x.max(min).min(max));}
}
